oxy_webhelp_navlinks = {"aws_gateway_kms_key_centralized_exo-d39536e17180":{"topics":[{"title":"Configuring a gateway KMS key","shortdesc":"<p class=\"shortdesc\">Configure a customer-managed KMS key for each region to encrypt intermediate         snapshots created during archival, indexing, and related operations in the centralized         Exocompute model.<\/p>","href":"saas\/aws_configuring_gateway_kms_key.html","attributes":{"data-id":"aws_configuring_gateway_kms_key"},"menu":{"hasChildren":false},"tocID":"aws_configuring_gateway_kms_key-d39536e17194","topics":[]},{"title":"Snapshot storage for PMK-encrypted AWS workloads","shortdesc":"<p class=\"shortdesc\">For AWS workloads, such as EC2 instances and EBS volumes encrypted with a         platform-managed key, <span class=\"ph\">RSC<\/span> re-encrypts snapshots using the gateway KMS key         when Exocompute tasks such as archiving, indexing, or cross-account replication are         configured, and stores the re-encrypted copy as the primary snapshot.<\/p>","href":"saas\/aws_snapshot_storage_pmk_encrypted_wkl.html","attributes":{"data-id":"aws_snapshot_storage_pmk_encrypted_wkl"},"menu":{"hasChildren":false},"tocID":"aws_snapshot_storage_pmk_encrypted_wkl-d39536e17205","topics":[]}]}};